package com.bank.fraud.consumer;

import org.apache.kafka.clients.consumer.Consumer;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.kafka.support.Acknowledgment;
import org.springframework.stereotype.Component;
import lombok.extern.slf4j.Slf4j;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;

@Component
@Slf4j
public class FraudScoreConsumer {

    // Bounded internal queue = application backpressure. If full, we pause fetching.
    private final BlockingQueue<String> workQueue = new ArrayBlockingQueue<>(5000);

    @KafkaListener(topics = "card.auth", groupId = "fraud-scorer")
    public void onAuth(String authEvent, Acknowledgment ack, Consumer<?, ?> consumer) {
        boolean queued = workQueue.offer(authEvent);
        if (!queued) {
            // Queue full: pause this consumer's partitions so Kafka stops handing us
            // messages we cannot yet process. This is backpressure Kafka won't do for us.
            consumer.pause(consumer.assignment());
            log.warn("Work queue full — paused fetching to apply backpressure");
            return; // do not ack; we will re-poll after resume
        }
        // A worker pool drains workQueue, runs the slow fraud model, then acks.
        ack.acknowledge();
    }

    // Called by the worker pool when the queue has drained below a low watermark.
    public void onQueueDrained(Consumer<?, ?> consumer) {
        consumer.resume(consumer.assignment());
        log.info("Work queue drained — resumed fetching");
    }
}
