package com.bank.fraud.demo;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class BackpressureDemo {

    private static final Logger log = Logger.getLogger(BackpressureDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        int producerRate = 2000;        // events/sec
        int retentionSeconds = 6 * 3600; // 6h retention
        long retentionCapacity = (long) producerRate * retentionSeconds;

        log.info("=== Before fix: 1 consumer group @ 1200/sec (structurally slow) ===");
        ConsumerGroup slow = new ConsumerGroup(1200);
        simulate(producerRate, slow, retentionCapacity, 8 * 3600, log);

        log.info("=== Fix 1: scale consumers to match (12 partitions, 2400/sec) ===");
        ConsumerGroup fast = new ConsumerGroup(2400);
        simulate(producerRate, fast, retentionCapacity, 8 * 3600, log);

        log.info("=== Fix 2: application backpressure keeps memory bounded ===");
        BoundedWorkQueue q = new BoundedWorkQueue(5000);
        for (int i = 0; i < 12000; i++) {
                if (!q.offer()) { log.fine("paused: queue full at " + q.size());
                break; }
        }
        log.info("Bounded queue held at capacity " + q.size()
                + " (consumer paused instead of exhausting heap)");
    }

    private static void simulate(int producerRate, ConsumerGroup group,
                                 long retentionCapacity, int seconds, Logger log) {
        long lag = 0;
        long droppedByRetention = 0;
        for (int t = 1; t <= seconds; t++) {
            lag += producerRate;                 // produced this second
            long consumed = Math.min(lag, group.ratePerSecond());
            lag -= consumed;                     // consumed this second
            if (lag > retentionCapacity) {
                long overflow = lag - retentionCapacity;
                droppedByRetention += overflow;  // oldest events deleted unread
                lag = retentionCapacity;
            }
        }
        long finalLag = lag;
        long finalDropped = droppedByRetention;
        if (finalDropped > 0) {
            log.severe("Final lag=" + finalLag + " events; DROPPED by retention="
                    + finalDropped + " (fraud checks NEVER ran — silent loss)");
        } else {
            log.info("Final lag=" + finalLag + " events; nothing dropped, consumer keeps up");
        }
    }
}

