class PartitionedTopic {
    final int partitions;
    PartitionedTopic(int partitions) { this.partitions = partitions; }
    // Max useful consumers in a group equals partition count.
    int maxConsumers() { return partitions; }
}

// ─── Would be in BoundedWorkQueue.java in a real project ───
class BoundedWorkQueue {
    private final int capacity;
    private int size = 0;
    BoundedWorkQueue(int capacity) { this.capacity = capacity; }
        boolean offer() { if (size >= capacity) return false; size++;
        return true; }
    int size() { return size; }
}

